// Makes a private team_id for the link. Nothing is sent here.
// Email text for the setup flow: the captain's invite and the players' intro. JavaScript only (runs in n8n Code nodes).
// tests/test_setup_import.py runs it in Node.js. Nothing here sends anything; a separate, switched-off Gmail node does that.

const esc = (s) => String(s === null || s === undefined ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const firstName = (name) => String(name || '').trim().split(/\s+/)[0] || 'there';

const BUTTON = 'display:inline-block;background:#1f5d46;color:#ffffff;text-decoration:none;padding:12px 22px;border-radius:8px;font-weight:600';
const WRAP = 'font-family:Helvetica,Arial,sans-serif;font-size:15px;line-height:1.5;color:#1b2420;max-width:560px';

// args: { captain_name, captain_email, base_url, form_path, team_id, now_iso }
function makeInvite(a) {
  const link = `${a.base_url}/form/${a.form_path}?team_id=${encodeURIComponent(a.team_id)}`;
  const expires = new Date(Date.parse(a.now_iso) + 7 * 86400000).toISOString();
  const first = firstName(a.captain_name);
  const html = [
    `<div style="${WRAP}">`,
    `<p>Hi ${esc(first)},</p>`,
    '<p><b>WhosOn</b> helps ALTA captains with the weekly scramble. It emails each of your players to ask who can play, reads their replies (even messy ones like "can\'t, my kid has a recital"), and puts together lineups that follow ALTA\'s rules.</p>',
    '<p><b>You stay in charge.</b> You approve every lineup, and every message to your team, before anything goes out.</p>',
    '<p>Setup takes about 10 minutes, once per season. You will confirm your league and season, then upload your roster and your schedule (Excel or CSV).</p>',
    `<p style="margin:24px 0"><a href="${esc(link)}" style="${BUTTON}">Set up my team</a></p>`,
    '<p style="color:#56625a;font-size:13px">This link is private to you and works for 7 days. If it stops working, reply to this email and we will send a new one.</p>',
    '</div>',
  ].join('');
  return {
    team_id: a.team_id,
    captain_name: a.captain_name,
    captain_email: String(a.captain_email).trim().toLowerCase(),
    invited_at: a.now_iso,
    expires_at: expires,
    link,
    subject: 'Set up your team with WhosOn',
    html,
  };
}

// args: { captain_name, league, season, players: [{ name, email }] }. Returns one email per player.
function makeIntroEmails(a) {
  const captain = a.captain_name || 'Your captain';
  return a.players.map((p) => ({
    to: p.email,
    name: p.name,
    subject: `${captain} is using WhosOn for your ${a.league} team`,
    html: [
      `<div style="${WRAP}">`,
      `<p>Hi ${esc(firstName(p.name))},</p>`,
      `<p>${esc(captain)} has set up <b>WhosOn</b> to help run your ${esc(a.league)} team this ${esc(a.season)} season.</p>`,
      '<p>Before each match you will get a short email asking if you can play. <b>Just reply in your own words</b>, like "yes", "can\'t, out of town", or "I can play but I have to leave by 4". The agent reads your reply, and may ask one follow-up if it is not sure.</p>',
      `<p>${esc(captain)} approves every lineup and every message to the team.</p>`,
      '<p style="color:#56625a;font-size:13px">If you would rather not get these emails, reply "no thanks" and your captain will be told.</p>',
      '</div>',
    ].join(''),
  }));
}

// ---------------------------------------------------------------- the lineup entry sheet (sent to the captain after she approves)

const MONTH_ABBR = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const ordinal = (n) => `${n}${[11, 12, 13].includes(n % 100) ? 'th' : { 1: 'st', 2: 'nd', 3: 'rd' }[n % 10] || 'th'}`;

function clock12(hhmm) {
  const [h, m] = String(hhmm).split(':').map(Number);
  return `${h % 12 || 12}:${String(m).padStart(2, '0')} ${h < 12 ? 'AM' : 'PM'}`;
}

// Standard ALTA start time for a line: lines 1-2 first slot, 3-4 second slot, 5 third slot.
const startFor = (line, startTimes) => startTimes[Math.min(Math.ceil(line / 2), startTimes.length) - 1];

// args: { captain_name, league, season, year, level_flight, week, date (YYYY-MM-DD), home_away, opponent, facility,
//         start_times: ['13:00','14:00','15:00'], lineup: [[nameA, nameB] x lines], line_times?: { 3: '10:00' }, comment?, reasons?: [text per line] }
// Lays the lineup out like ALTA's lineup page so the captain can copy it across. Sending nothing; the captain presses Publish herself on ALTA.
function makeEntrySheet(a) {
  const [y, mo, d] = a.date.split('-').map(Number);
  const dateShort = `${MONTH_ABBR[mo - 1]} ${d}`;
  const dateUS = `${String(mo).padStart(2, '0')}/${String(d).padStart(2, '0')}/${y}`;
  const where = a.home_away === 'home' ? 'HOME' : 'AT';
  const title = `${a.year} ${a.season} ${a.league}${a.level_flight ? ' ' + a.level_flight : ''}`;
  const overrides = a.line_times || {};
  const TD = 'padding:8px 12px;border-bottom:1px solid #d9dfda;vertical-align:top';
  const rows = a.lineup.map((pair, i) => {
    const line = i + 1;
    const time = overrides[line] || startFor(line, a.start_times);
    const changed = !!overrides[line] && overrides[line] !== startFor(line, a.start_times);
    const reason = a.reasons && a.reasons[i] ? `<div style="color:#56625a;font-size:12px;margin-top:4px">${esc(a.reasons[i])}</div>` : '';
    return `<tr><td style="${TD};font-weight:700">${line}D</td>`
      + `<td style="${TD}">${esc(String(pair[0]).toUpperCase())}<br>${esc(String(pair[1]).toUpperCase())}${reason}</td>`
      + `<td style="${TD};white-space:nowrap">${dateUS} ${clock12(time)}${changed ? '<br><span style="color:#b35c00;font-size:12px">different from the usual time</span>' : ''}</td></tr>`;
  }).join('');
  const comment = a.comment
    ? `<p style="margin:16px 0 4px;font-weight:700">Comment to paste into ALTA</p><div style="background:#f2f5f3;border-radius:6px;padding:10px 12px;white-space:pre-wrap">${esc(a.comment)}</div>`
    : '';
  const html = [
    `<div style="${WRAP}">`,
    `<p>Hi ${esc(firstName(a.captain_name))},</p>`,
    '<p>Your lineup is approved. Here it is laid out like ALTA\'s lineup page, so you can copy it across in a couple of minutes.</p>',
    `<h2 style="margin:20px 0 2px;color:#1f5d46">${esc(title)}</h2>`,
    `<div style="color:#56625a;margin-bottom:12px">Week ${a.week} (${esc(dateShort)}) ${where} ${esc(String(a.facility || a.opponent || '').toUpperCase())}${a.opponent && a.facility ? ' vs ' + esc(a.opponent) : ''}</div>`,
    `<table style="border-collapse:collapse;width:100%"><tr><th style="${TD};text-align:left">Line</th><th style="${TD};text-align:left">Players</th><th style="${TD};text-align:left">Match time</th></tr>${rows}</table>`,
    comment,
    '<p style="margin-top:20px"><b>To finish:</b> open your lineup on the ALTA site, pick these players on each line, check the match times, then press <b>Publish</b> yourself. The agent never logs in to ALTA or publishes for you.</p>',
    '<p style="color:#56625a;font-size:13px">The agent checked this lineup against ALTA\'s movement and sandbagging rules before sending it. ALTA\'s own lineup page will also check it when you publish.</p>',
    '</div>',
  ].join('');
  return { subject: `Week ${a.week} lineup for ${a.league}: copy it into ALTA`, html };
}

function randomId() {
  try { return require('crypto').randomBytes(18).toString('hex'); } catch (e) { /* not available here */ }
  try { return crypto.randomUUID().replace(/-/g, '') + crypto.randomUUID().replace(/-/g, '').slice(0, 4); } catch (e) { /* not available here */ }
  return Array.from({ length: 36 }, () => Math.floor(Math.random() * 16).toString(16)).join('');
}
const input = $input.first().json;
const invite = makeInvite({ ...input, form_path: 'tca-setup-2-league', team_id: input.team_id || randomId(), now_iso: input.now_iso || new Date().toISOString() });
